// كل الحساب هنا — بالكود، لا بالنموذج.
// النماذج اللغوية تخطئ بالحساب، ورقم خاطئ بتقرير أسبوعي يهدم ثقة العميل كلها.
// دور النموذج لاحقاً هو الصياغة فقط، على أرقام محسوبة سلفاً.

const MS_DAY = 86400000;
const rows = $input.all().map(i => i.json);

// الأعمدة المتوقعة — يعدّلها المنفّذ لكل عميل. هذا هو سطح التخصيص الوحيد.
const COL = { date: 'date', amount: 'amount', category: 'category', customer: 'customer' };

const now = new Date();
const startThis = new Date(now.getTime() - 7 * MS_DAY);
const startPrev = new Date(now.getTime() - 14 * MS_DAY);

const parse = r => {
  const d = new Date(r[COL.date]);
  const amount = Number(String(r[COL.amount] ?? '').replace(/[^0-9.-]/g, ''));
  return { d, amount: Number.isFinite(amount) ? amount : 0, row: r };
};

const clean = rows.map(parse).filter(x => !isNaN(x.d.getTime()));
const skipped = rows.length - clean.length;

const thisWeek = clean.filter(x => x.d >= startThis);
const prevWeek = clean.filter(x => x.d >= startPrev && x.d < startThis);

const sum   = a => a.reduce((t, x) => t + x.amount, 0);
const money = n => Math.round(n * 100) / 100;

// النسبة تُحسب فقط إذا كانت القاعدة غير صفرية — القسمة على صفر تنتج Infinity
// وتظهر بالتقرير كـ"نمو ∞%" وهذا يفضح النظام أمام العميل.
const pct = (a, b) => (b === 0 ? null : Math.round(((a - b) / b) * 1000) / 10);

const revThis = sum(thisWeek), revPrev = sum(prevWeek);

const byKey = (arr, key) => {
  const m = {};
  for (const x of arr) {
    const k = String(x.row[key] ?? 'غير محدد').trim() || 'غير محدد';
    m[k] = (m[k] || 0) + x.amount;
  }
  return Object.entries(m)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 5)
    .map(([name, total]) => ({ name, total: money(total) }));
};

return [{
  json: {
    period: {
      from: startThis.toISOString().slice(0, 10),
      to:   now.toISOString().slice(0, 10)
    },
    revenue: {
      current:  money(revThis),
      previous: money(revPrev),
      changePct: pct(revThis, revPrev)
    },
    orders: {
      current:  thisWeek.length,
      previous: prevWeek.length,
      changePct: pct(thisWeek.length, prevWeek.length)
    },
    averageOrder: {
      current:  thisWeek.length ? money(revThis / thisWeek.length) : 0,
      previous: prevWeek.length ? money(revPrev / prevWeek.length) : 0
    },
    topCategories: byKey(thisWeek, COL.category),
    topCustomers:  byKey(thisWeek, COL.customer),
    dataQuality: { totalRows: rows.length, skippedRows: skipped }
  }
}];

